const D = { density: .55, energy: .6, hue: 285, speed: 1, scale: 1, warp: .3, x: .5, y: .46, seed: 0, style: 'grid', act: 'cruise' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const hz = cl(P.y, .28, .72) * height;
const cx = cl(P.x, .05, .95) * width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t, 1.7) * groundH;
const hwOf = t => width * (.045 + t * .95) * .5 * P.scale;
const NR = Math.round(9 + P.density * 34);
const NC = Math.round(6 + P.density * 18);
const H = P.hue;
const CO = (P.hue + 150) % 360;  // complementary accent

S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);

// real-time scroll (integrate seconds -> never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.5 + .8*K.intensity);
if (P.act === 'pulse') sp *= 1 + 1.1*kick;
if (P.act === 'warpdrive') sp *= 1.3 + 1.6*(.5 + .5*Math.sin(K.t*.045 + K.section*.8));
S.scroll = (S.scroll||0) + dt*sp*.6;
const scroll = S.scroll;
S.warpF = (S.warpF||0)*.9 + (P.act==='warpdrive'? (.6+.8*Math.abs(Math.sin(K.t*.045))) : (.15+.6*kick))*.1;

// ---- cached structural base (deep-space gradient + static stars) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*8)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 60;
  // deep space sky
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz;
    let h,s,b;
    if (sty==='blueprint'){ h=H; s=55; b=8+6*f; }
    else if (sty==='nebula'){ h=H; s=48; b=5+9*(1-f); }
    else { h=H; s=52+18*f; b=3+7*(1-f); }  // grid / warp deep void
    g.fill(h,cl(s,4,90),cl(b,2,80),100); g.rect(0,y,width,hz/STR+1);
  }
  // nebula clouds (static shells; brights added live)
  if (sty==='nebula'){ g.push(); g.blendMode(ADD);
    for(let n=0;n<3;n++){ const nh=(H+n*60)%360;
      for(let p=0;p<70;p++){ const px=fr(n*99+p)*width, py=fr(n*99+p+40)*hz*1.1, r=hz*(.15+.25*fr(n*99+p+7));
        g.fill(nh,60,70,4); g.ellipse(px,py,r,r*.7); } } g.pop(); }
  // ground void
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR);
    let h,s,b;
    if (sty==='blueprint'){ h=H; s=60; b=6+4*t; }
    else { h=H; s=55-15*t; b=cl(2+6*t,2,26); }
    g.fill(h,cl(s,3,90),b,100); g.rect(0,y,width,(y2-y)+1);
  }
  // static starfield in the sky (drift copy added live over ground)
  g.push(); g.blendMode(ADD);
  const NS = sty==='blueprint'?60:200;
  for(let i=0;i<NS;i++){ const sx=fr(i*3)*width, syy=fr(i*3+1)*hz*.98, mag=fr(i*3+2);
    const bb = sty==='blueprint'? 55 : 100;
    g.fill(sty==='nebula'?(H+40)%360:H+8, sty==='blueprint'?40:12, bb, 20+60*mag);
    const r=sty==='blueprint'?.8: (.6+2.2*mag);
    g.ellipse(sx,syy,r,r); }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- live nebula drift (nebula style) ----
if (sty==='nebula'){ push(); blendMode(ADD); noStroke();
  for(let n=0;n<3;n++){ const nh=(H+30+n*55)%360;
    for(let p=0;p<26;p++){ const ph=p*.6+n*2+K.t*(.03+.01*n);
      const px=(fr(n*50+p)*width + Math.sin(ph)*40)%width;
      const py=hz*(.15+.6*fr(n*50+p+11)) + Math.cos(ph*1.3)*20;
      const r=hz*(.12+.16*fr(n*50+p+3));
      fill(nh,65,88,(4+5*Math.sin(ph*2))*glow); ellipse(px,py,r,r*.65); } }
  pop(); }

// ---- live perspective grid ----
noFill();
for (let r=0; r<=NR; r++){
  let t = (r - (scroll%1)) / NR;
  if (t<=0 || t>1) continue;
  const y = yOf(t), hw = hwOf(t), near=t;
  let h,s,b,a,sw;
  if (sty==='blueprint'){ h=H; s=70; b=100; a=22+50*near; sw=.6+near*1.1; }
  else if (sty==='nebula'){ h=(H+40)%360; s=40; b=100; a=8+34*near; sw=.5+near*1.4; }
  else if (sty==='warp'){ h=CO; s=85; b=100; a=10+46*near; sw=.5+near*1.6; }
  else { h=CO; s=90; b=100; a=18+64*near; sw=.7+near*2.4; } // grid neon
  stroke(h,s,b, a*(.55+.6*glow));
  strokeWeight(sw);
  if (sty==='grid'||sty==='warp'){ drawingContext.shadowBlur=(3+13*near)*glow; drawingContext.shadowColor=color(h,90,100,90).toString(); }
  line(cx-hw, y, cx+hw, y);
  if (sty==='blueprint'){ // tick marks
    for(let k=0;k<=4;k++){ const u=k/4, xx=cx-hw+u*2*hw; stroke(H,60,100,a*.7); line(xx,y-2,xx,y+2); }
  }
}
drawingContext.shadowBlur = 0;

// converging verticals (tron rays)
const warp = P.warp;
for (let c=0; c<=NC; c++){
  const u=c/NC, d=(u-.5);
  const xTop=cx + d*width*.03*P.scale;
  const xBot=cx + d*width*1.9*P.scale*(1+warp*1.2*d*d*4);
  let h,s,b,a,sw;
  if (sty==='blueprint'){ h=H; s=65; b=100; a=30; sw=.7; }
  else if (sty==='nebula'){ h=(H+40)%360; s=35; b=95; a=16; sw=.8; }
  else { h=H; s=88; b=100; a=30; sw=1.0; }
  stroke(h,s,b, a*(.55+.5*glow)); strokeWeight(sw);
  if (sty==='grid'||sty==='warp'){ drawingContext.shadowBlur=6*glow; drawingContext.shadowColor=color(h,90,100,80).toString(); }
  line(xTop, hz, xBot, height);
}
drawingContext.shadowBlur = 0;

// ---- warp-speed star streaks (always on; the real-time motion floor) ----
const NP = Math.round(60 + P.density * 150);
push(); blendMode(ADD); noStroke();
const wf = cl(S.warpF, 0, 1);
for (let i=0;i<NP;i++){
  const ang = fr(i*2)*6.28318, rad0 = fr(i*2+1);
  // progress travels outward from vanishing point in real time
  let prog = (rad0 + K.t*(.05+.13*fr(i*2+3))*(P.speed) + scroll*.02) % 1;
  const rr = Math.pow(prog, 2.2);
  const reach = Math.min(width,height)*.75;
  const dx = Math.cos(ang)*rr*reach, dy = Math.sin(ang)*rr*reach*.7;
  const x = cx + dx, y = hz*.62 + dy;
  const streak = (6 + 40*rr)*(1+wf*1.4);
  const px = x - Math.cos(ang)*streak, py = (hz*.62+dy) - Math.sin(ang)*streak*.7;
  const h = sty==='nebula'?(H+50)%360 : (sty==='blueprint'?H:H+6);
  const a = Math.min(50, (6+34*rr)*(.5+.9*glow)*(1+.7*S.tre));
  stroke(h, sty==='blueprint'?30:16, 100, a); strokeWeight(.6+rr*2.2*(1+wf));
  line(px,py,x,y);
}
pop();

// horizon light bloom on the beat (partial, safe)
push(); blendMode(ADD); noStroke();
const flare=(kick*.6+K.swell*.3)*glow;
for(let i=0;i<5;i++){ const rr=(5-i)*groundH*.05*(1+flare);
  fill(CO, 70, 96, 4+9*flare); rect(0, hz-rr*.4, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
